class Solution {
    vector<vector<int>> adj;
    vector<bool>* apple;
    int result;

    bool dfs(int u, int parent) {
        bool has = (*apple)[u];
        for (int v : adj[u]) {
            if (v == parent) continue;
            if (dfs(v, u)) {
                result += 2;
                has = true;
            }
        }
        return has;
    }
public:
    int minTime(int n, vector<vector<int>>& edges, vector<bool>& hasApple) {
        adj.assign(n, {});
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        apple = &hasApple;
        result = 0;
        dfs(0, -1);
        return result;
    }
};
